namespace OrdersApi.Models;

/// <summary>Represents the lifecycle status of an order.</summary>
public enum OrderStatus
{
    Pending,
    Processing,
    Shipped,
    Delivered,
    Cancelled
}

using OrdersApi.Models;

namespace OrdersApi.Models;

/// <summary>Represents an order returned by the API.</summary>
public sealed record OrderResponse(
    int Id,
    int CustomerId,
    DateTimeOffset PlacedAt,
    decimal TotalAmount,
    OrderStatus Status);

using System.ComponentModel.DataAnnotations;

namespace OrdersApi.Models;

/// <summary>Payload for creating a new order.</summary>
public sealed record CreateOrderRequest
{
    /// <summary>The ID of the customer placing the order.</summary>
    [Required]
    public required int CustomerId { get; init; }

    /// <summary>The total monetary amount for the order.</summary>
    [Range(0.01, double.MaxValue)]
    public required decimal TotalAmount { get; init; }
}

using OrdersApi.Models;

namespace OrdersApi.Services;

public interface IOrderService
{
    Task<IReadOnlyList<OrderResponse>> GetAllAsync(CancellationToken ct);
    Task<OrderResponse?> GetByIdAsync(int id, CancellationToken ct);
    Task<OrderResponse> CreateAsync(CreateOrderRequest request, CancellationToken ct);
}

using OrdersApi.Models;

namespace OrdersApi.Services;

public sealed class OrderService : IOrderService
{
    private readonly List<OrderResponse> _orders = [];
    private int _nextId = 1;

    public Task<IReadOnlyList<OrderResponse>> GetAllAsync(CancellationToken ct)
    {
        return Task.FromResult<IReadOnlyList<OrderResponse>>(_orders.AsReadOnly());
    }

    public Task<OrderResponse?> GetByIdAsync(int id, CancellationToken ct)
    {
        var order = _orders.FirstOrDefault(o => o.Id == id);
        return Task.FromResult(order);
    }

    public Task<OrderResponse> CreateAsync(CreateOrderRequest request, CancellationToken ct)
    {
        var order = new OrderResponse(
            Id: _nextId++,
            CustomerId: request.CustomerId,
            PlacedAt: DateTimeOffset.UtcNow,
            TotalAmount: request.TotalAmount,
            Status: OrderStatus.Pending);

        _orders.Add(order);
        return Task.FromResult(order);
    }
}

using Microsoft.AspNetCore.Mvc;
using OrdersApi.Models;
using OrdersApi.Services;

namespace OrdersApi.Controllers;

[ApiController]
[Route("api/[controller]")]
public class OrdersController : ControllerBase
{
    private readonly IOrderService _service;

    public OrdersController(IOrderService service)
    {
        _service = service;
    }

    /// <summary>Returns all orders.</summary>
    [HttpGet]
    [ProducesResponseType(typeof(IReadOnlyList<OrderResponse>), StatusCodes.Status200OK)]
    public async Task<ActionResult<IReadOnlyList<OrderResponse>>> GetAll(
        CancellationToken cancellationToken)
    {
        return Ok(await _service.GetAllAsync(cancellationToken));
    }

    /// <summary>Returns a single order by ID.</summary>
    [HttpGet("{id}")]
    [ProducesResponseType(typeof(OrderResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status404NotFound)]
    public async Task<ActionResult<OrderResponse>> GetById(
        int id, CancellationToken cancellationToken)
    {
        var order = await _service.GetByIdAsync(id, cancellationToken);
        return order is null ? NotFound() : Ok(order);
    }

    /// <summary>Creates a new order.</summary>
    [HttpPost]
    [ProducesResponseType(typeof(OrderResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(StatusCodes.Status400BadRequest)]
    public async Task<ActionResult<OrderResponse>> Create(
        CreateOrderRequest request, CancellationToken cancellationToken)
    {
        var order = await _service.CreateAsync(request, cancellationToken);
        return CreatedAtAction(nameof(GetById), new { id = order.Id }, order);
    }
}

