    private readonly List<OrderResponse> _orders = [];
    private int _nextId = 1;

    public Task<IReadOnlyList<OrderResponse>> GetAllAsync(CancellationToken ct)
    {
        return Task.FromResult<IReadOnlyList<OrderResponse>>(_orders.AsReadOnly());
    }

    public Task<OrderResponse?> GetByIdAsync(int id, CancellationToken ct)
    {
        var order = _orders.FirstOrDefault(o => o.Id == id);
        return Task.FromResult(order);
